namespace Scheduling;

/// <summary>Finds the first calendar slot that fits a required duration.</summary>
public sealed class SlotFinder
{
    public Slot? FindFirstFit(Resource resource, TimeSpan duration, DateTime notBefore)
    {
        if (!CanSearch(resource, duration))
            return null;

        foreach (var slot in resource.Calendar)
        {
            if (IsEligible(slot, duration, notBefore))
                return slot;
        }

        return null;
    }

    private static bool CanSearch(Resource resource, TimeSpan duration)
    {
        return resource.Calendar.Count > 0 && duration > TimeSpan.Zero;
    }

    private static bool IsEligible(Slot slot, TimeSpan duration, DateTime notBefore)
    {
        if (slot.Start < notBefore)
            return false;

        var length = slot.End - slot.Start;
        return length >= duration
            && slot.Start.Hour >= 8
            && slot.Start.Hour <= 18
            && slot.End.Hour <= 20;
    }
}
